"""Current public proposal and service offer; no model collection or transport."""
from pathlib import Path
import re

ROOT = Path(__file__).resolve().parents[1]


def intro(kicker, title, lead):
    return f'<section class="intro"><p class="eyebrow">{kicker}</p><h1>{title}</h1><p class="lead">{lead}</p></section>'


def publish(page, out):
    old = (out / 'program.html').read_text(encoding='utf-8')
    body = re.search(r'<main id="main" tabindex="-1">(.*?)</main>', old, re.S).group(1)
    page('program-archive.html', 'Earlier program proposal — archive',
         '<section class="reading"><div class="notice"><strong>Archived proposal / October 2, 2026</strong><p>This earlier USD40,000 roadmap is preserved for provenance. The current request is a smaller, gated feasibility study.</p><a href="/program.html">Current research proposal →</a></div></section>' + body,
         'Archived MurderBench roadmap, retained with its earlier scope and provisional funding estimate.')

    page('index.html', 'Test the safeguards around your AI agent', '''
<section class="hero"><div><p class="eyebrow">INDEPENDENT AI AGENT EVALUATION</p><h1>The safeguard passed.<br>Was the action<br>safe<span class="accent">?</span></h1><p class="lead">MurderBench tests the gap between what an agent’s safeguards check and what its actions actually do.</p><div class="actions"><a class="button" href="/guardrail-coverage.html">Explore the proposed study ↗</a><a href="/services.html">Discuss an evaluation →</a></div><p class="caption">Executable controls. Recorded effects. Useful work measured alongside risk.</p></div><aside class="specimen" aria-label="Proposed experiment, not a model result"><div class="record-head">NEXT EXPERIMENT <span>PROPOSAL</span></div><p class="record-id">MB / GUARDRAIL COVERAGE / 01</p><h2>Same checks.<br>Different name.</h2><dl><div><dt>Guard</dt><dd>Checks action bounds and step limits</dd></div><div><dt>A</dt><dd>“Motion validator”</dd></div><div><dt>B</dt><dd>“Safety approver”</dd></div><div><dt>Question</dt><dd>Does the agent take more risk?</dd></div></dl><p class="caption">Both conditions disclose the same coverage. No model trials or measured effect for this proposal yet.</p></aside></section>
<div class="ticker"><span>TOOL USE</span><span>GUARDRAIL COVERAGE</span><span>EXECUTED EFFECTS</span><span>TESTED REPAIRS</span></div>
<section class="split"><div><p class="eyebrow">THE DECISION</p><h2>Keep it.<br>Change it.<br>Replace it.</h2></div><div><p class="large">A safety evaluation should help an operator choose a configuration.</p><p>We compare a safeguard with a specific repair, replay the resulting actions, and measure the effect on ordinary useful tasks. The output is a bounded engineering decision with evidence and limits.</p><a class="text-link" href="/services.html">What an engagement delivers ↗</a></div></section>
<section><div class="section-head"><p class="eyebrow">PUBLIC RECORD</p><h2>Results include reasons to stop.</h2></div><div class="columns"><article><p class="number">01 / COMPLETED STUDY</p><h3>Updating after a state change</h3><p>The first scoped proposal study measured responses to changed permission and safety conditions. Its limits are explicit; it does not establish general alignment.</p><a href="/results.html">Read the results →</a></article><article><p class="number">02 / INCOMPLETE PILOT</p><h3>A test that proved too easy</h3><p>The matched pilot completed 123 of 192 planned episodes. Its trusted rescue certificate made the task easy, and it did not establish the intended contribution.</p><a href="/matched-pilot.html">Read the pilot →</a></article><article><p class="number">03 / REJECTED CANDIDATE</p><h3>Remediation versus recovery</h3><p>A real credential-revocation mechanism was reproduced. It duplicated established operational problems, so model collection stopped before spending.</p><a href="/remediation-recovery.html">Read the rejection →</a></article></div></section>
<section class="dark split"><div><p class="eyebrow">NEXT QUESTION / NOT A FINDING</p><h2>Can a safety label<br>make an agent<br>less safe?</h2></div><div><p>Robot safety and responsibility diffusion already have substantial prior work. Our candidate isolates the description of an unchanged, partial guard and tests whether an explicit coverage statement improves outcomes.</p><p>We are seeking critical review, API credits and a replication partner before a frozen model comparison.</p><a class="button light" href="/program.html">Review or support the study ↗</a></div></section>
''', 'Independent evaluation of AI agent safeguards: replayable controls, executed effects and tested repairs. Current proposal and previous negative findings.')

    page('guardrail-coverage.html', 'Can a safety label make an agent less safe?', intro(
        'PROPOSED STUDY / OCTOBER 4, 2026', 'Can a safety label<br>make an agent<br>less safe?',
        'Change the description of a safeguard. Keep its code, coverage facts and task fixed. Measure what the agent actually executes.') + '''
<section class="reading"><div class="notice"><strong>Hypothesis, not a result.</strong><p>This is a reviewable proposal. No model trials have been run for it. The protocol, native interface and confirmation design are not frozen.</p></div><h2>The boundary worth testing</h2><p>A motion validator can check action bounds and per-step movement without checking whether a permitted movement is appropriate for the object in the scene. An agent that knows those limits still has to make the remaining judgment.</p><p>Our proposed comparison calls that same component either a “motion validator” or a “safety approver.” Both descriptions disclose identical coverage facts. Any measured difference would concern this controlled wording intervention, not proof of a model’s motives or an effect of alignment training.</p></section>
<section><figure class="matched-figure"><img src="/guardrail-coverage-design.svg" width="1200" height="520" alt="Proposed experiment: identical task, observations and motion guard; neutral validator wording compared with safety-approver wording; a separate explicit-limits repair; replay unsafe effects and useful completion. No results yet."><figcaption class="caption">Study design only. Arrows show planned comparisons; no outcome rates or model findings are represented.</figcaption></figure></section>
<section class="reading"><h2>What would make this useful?</h2><p>The decision is concrete: should an operator change the instruction describing a guard, explicitly assign responsibility for uncovered hazards, or replace the guard with one that enforces the relevant constraint?</p><p>A repair must reduce unsafe effects without merely blocking ordinary work. The full semantic guard is a control for prevention; the explicit-limits instruction is a separate repair comparison because it adds information.</p><h2>Controls before model calls</h2><ul><li>A correct scripted policy completes benign tasks and available safe alternatives.</li><li>A deliberately faulty policy demonstrates a hazard that the partial guard admits.</li><li>A guard enforcing the full scenario constraint prevents that faulty execution.</li><li>An independent event-log verifier reconstructs proposed actions, guard decisions and state effects.</li><li>Fresh confirmation cases test a pilot effect; missing and technically invalid attempts remain visible.</li></ul><p>Hazards must be independently legible. Impossible situations, failed transport and inability to complete a benign task are separate outcomes. Recognition checks use fresh episodes so they cannot prime the action test.</p><h2>Native calibration, with limits</h2><p>The pinned Inspect Robots core guard accepted two permitted synthetic displacements that crossed an unrelated semantic rule. Bounds, per-step limiting and non-finite rejection behaved as documented. This is an expected coverage boundary, not a novel failure or a model result. Additional embodiment guards may check more. Per-step movement is not a dynamic speed guarantee.</p><p><a href="/artifacts/guardrail-source-audit-2026-10-04.txt">Source audit and reproduction instructions ↓</a> · <a href="/artifacts/guardrail-native-primitive.json">Native primitive receipt ↓</a></p><h2>The closest work is already strong</h2><p><a href="https://robocurve.org/roboharm/">RoboHarm</a> evaluates unsafe instructions in fixed robot scenes, and <a href="https://arxiv.org/abs/2410.13691">RoboPAIR</a> demonstrates robot misuse. Neither a dangerous scene nor low refusal alone would earn a contribution here.</p><p><a href="https://arxiv.org/html/2609.27900v1">Delegated Misalignment</a> studies responsibility diffusion and role bias in principal/subordinate systems. Our proposed contrast keeps one agent and its task information fixed, with a non-agent guard. We are not claiming to discover responsibility diffusion.</p><p><a href="https://arxiv.org/html/2604.05172v1">ClawsBench</a> studies scaffolding effects, and <a href="https://arxiv.org/html/2503.07885v1">RoboGuard</a> studies robot guardrails and plan repair. A new harness or added semantic check alone is insufficient. The question is whether this particular contrast identifies a useful configuration choice.</p><p><a href="https://aclanthology.org/2025.nlp4dh-1.50/">Malberg et al.</a> already test risk compensation in LLMs. Their released experiment changes the stated risk after adding protection; our candidate would keep risk and coverage facts fixed. Executed actions alone would not establish a new contribution. <a href="https://arxiv.org/abs/2603.05786">Proof-of-Guardrail</a> already distinguishes guard execution from general safety.</p><p>The exact contrast was not identified in our limited audit. That is not proof that nobody has tested it. We welcome a pointer to closer published or unpublished work.</p><h2>What the earlier evidence cannot tell us</h2><p>A released RoboHarm transcript contains a downstream safety-assurance phrase. It motivates this hypothesis but cannot establish that the phrase caused an unsafe choice. MurderBench’s earlier pilots did not isolate this effect either.</p><p>No physical actuators, people or production resources will be exposed. We will use original synthetic scenes, respect dependency licenses, and publish routing failures and negative findings.</p><h2>Stop conditions</h2><p>Reject the study if it duplicates an existing evaluation, the guard gap cannot be faithfully reproduced, hazards are unobservable, controls fail, the task leaks an obvious answer, or the budget cannot support a meaningful comparison. An isolated mistake does not pass.</p><a class="button" href="/artifacts/guardrail-coverage-proposal.txt">Read the full proposal ↓</a><a class="text-link" href="/program.html">Review questions and support request →</a></section>
''', 'A proposed controlled experiment on safety-assurance wording and actual guard coverage. No model results yet; prior work, controls and rejection gates included.')

    page('program.html', 'Review and support the next study', intro(
        'RESEARCH SUPPORT / PROPOSAL', 'A small study.<br>A concrete decision.',
        'Help test whether an agent’s description of a safeguard changes its actions—and whether a specific repair improves the decision.') + '''
<section class="reading"><h2>Three useful contributions</h2><div class="rows"><article><h3>Method critique</h3><p>Identify the closest experiment, a confound in the wording contrast, or a native interface that would make the test more credible.</p></article><article><h3>Model access</h3><p>API credits or permitted research access let us test exact versions and confirm a result on fresh cases. We request credits before expanding cash spending.</p></article><article><h3>Independent replication</h3><p>Replay controls and review scene labels or reproduce a frozen contrast. No independent reviewer or partner is secured yet.</p></article></div><h2>Provisional feasibility request: USD7,500</h2><p>A four-week milestone proposal covers engineering (USD4,000), independent review (1,000), compute (500), replication (750), reporting and artifacts (750), and contingency (500). These are estimates; collaborators and vendor quotes are not secured. Work begins after access and reviewer availability are agreed.</p><p>First deliver the pinned executor, control traces and overlap decision. Then freeze a limited exploratory comparison. Spend on fresh confirmation only if the contribution and capability controls survive. A rejection or negative result satisfies the evidence deliverable; funding cannot require a dramatic finding.</p><p>The existing cash API cap remains USD100 for the lifetime program, including outstanding reservations. A grant request is not an authorization to exceed it.</p><h2>Independence is part of the scope</h2><p>We disclose sponsors and awarded credits. Funders cannot choose scores, suppress negative findings or purchase an endorsement. Confidentiality and any vulnerability disclosure window must be agreed before collection.</p><h2>Questions for a reviewer</h2><ol><li>Which published or released experiment already isolates the name of an unchanged partial guard?</li><li>Can the proposed A/B descriptions preserve equivalent facts and task authority?</li><li>Which executor implementation and scene controls make the difference operationally meaningful?</li><li>What confirmation result would cause an operator to change a real configuration?</li></ol><a class="button" href="mailto:linh@ngo.net?subject=MurderBench%20proposal%20review">Contact Linh Ngo ↗</a><a class="text-link" href="/guardrail-coverage.html">Study design →</a><a class="text-link" href="/artifacts/guardrail-coverage-proposal.txt">Full proposal ↓</a><a class="text-link" href="/artifacts/business-2026-10-04.txt">Operating plan ↓</a><h2>Earlier work and proposals</h2><p>The earlier remediation/recovery mechanism was rejected at the contribution gate. The matched pilot was incomplete and too easy to establish its intended claim. Those records remain public.</p><a class="text-link" href="/research.html">Study record →</a><a class="text-link" href="/program-archive.html">Archived USD40,000 roadmap →</a></section>
''', 'Seeking expert critique, model credits and milestone support for a controlled guardrail-coverage study, with publication independence and explicit stop conditions.')

    page('services.html', 'Evaluate an agent safeguard', intro(
        'SERVICES / SCOPED ENGAGEMENTS', 'Which safeguard<br>should you deploy?',
        'Bring one agent workflow and one configuration decision. We will scope a test that exposes what the safeguard covers, what it misses, and what a repair costs in useful work.') + '''
<section class="reading"><h2>A bounded evaluation</h2><p>For teams integrating models with tools, the first engagement compares the current safeguard with one proposed repair in a synthetic replica of a specific workflow.</p><div class="rows"><article><h3>Define the decision</h3><p>Agree the workflow, authority boundaries, hazards, benign tasks and the configuration choice the report must inform.</p></article><article><h3>Prove the controls</h3><p>Reproduce safe and deliberately faulty execution, document the tool semantics, and make event replay independently inspectable.</p></article><article><h3>Compare and report</h3><p>Record executed effects, useful completion, technical failures and costs. Deliver versioned code, traces, uncertainty and a recommendation bounded by the evidence.</p></article></div><h2>What you receive</h2><ul><li>A written threat model and an agreed acceptance test.</li><li>A reproducible local harness with synthetic resources.</li><li>A current-versus-repair comparison and benign-task controls.</li><li>A report identifying what changed, what remains uncertain and the deployment decision it supports.</li></ul><h2>Start with the workflow</h2><p>Send the agent’s task, tool interfaces, proposed safeguard and the decision you face. Do not send credentials, customer records or other confidential material in an initial inquiry. We agree scope, data handling, access limits, timing and a quote before work begins.</p><p>We do not certify general model safety or promise that an evaluation will discover a failure. MurderBench is an early evaluation initiative; no client engagements, external endorsements or production deployments are claimed.</p><a class="button" href="mailto:linh@ngo.net?subject=Agent%20safeguard%20evaluation">Discuss your workflow ↗</a><a class="text-link" href="/research.html">Inspect the public evidence →</a><h2>Public research and client work</h2><p>Public research preserves publication independence. A private engagement has an explicit disclosure agreement. Sponsorship does not buy favorable scores, and any material relationship behind a public report is disclosed.</p></section>
''', 'A scoped service to compare an AI agent safeguard with a tested repair, using synthetic controls, replayable traces and useful-task performance.')

    page('research.html', 'Studies and rejected candidates', intro(
        'PUBLIC RESEARCH RECORD', 'Follow the evidence.<br>Include the dead ends.',
        'Completed studies, incomplete pilots and rejected mechanisms are different outcomes. Each stays visible.') + '''
<section class="reading"><div class="rows"><article><h3>Guardrail coverage<br><span class="caption">PROPOSED / NO MODEL TRIALS</span></h3><p>Compare two descriptions of an unchanged partial guard. A repair must reduce unsafe effects while preserving useful completion. <a href="/guardrail-coverage.html">Read the proposal →</a></p></article><article><h3>Remediation and recovery<br><span class="caption">MECHANISM REPRODUCED / CONTRIBUTION REJECTED</span></h3><p>Vault revocation destroyed a dependent recovery path. The behavior overlapped established engineering problems, so collection stopped before model queries. <a href="/remediation-recovery.html">Read the rejection →</a></p></article><article><h3>Matched deadline pilot<br><span class="caption">INCOMPLETE / NO CLAIM VALIDATED</span></h3><p>123 of 192 planned episodes completed. A trusted rescue certificate made the tested choice easy; the pilot did not establish the intended contribution. <a href="/matched-pilot.html">Read the pilot →</a></p></article><article><h3>Deadline development<br><span class="caption">EXPLORATORY DEVELOPMENT</span></h3><p>Small native episodes and offline controls explored verification, delays and recovery. These informed later designs rather than a general safety ranking. <a href="/necessity.html">Read development notes →</a></p></article><article><h3>Changed-state proposals<br><span class="caption">COMPLETED / NARROW PROXY</span></h3><p>The first scoped study tested proposed actions after permission or safety conditions changed. Proposal behavior does not establish real-world alignment. <a href="/results.html">Read the results →</a></p></article></div><h2>Reproduce and challenge</h2><p>The <a href="https://github.com/fastrocket/murderbench">source repository</a> retains registrations, amendments, replay verifiers, reports and technical failures. Read each study’s limits before combining results across designs.</p><p>RoboHarm motivated the initiative. Our experiments and claims are independent; no affiliation or endorsement by Robocurve, governments or model providers is implied.</p><a class="text-link" href="/program.html">Review the next candidate →</a><a class="text-link" href="/coverage.html">Model and route coverage →</a></section>
''', 'The MurderBench evidence record: scoped model studies, incomplete pilots, rejected candidates and the next proposed guardrail experiment.')

    page('about.html', 'Linh Ngo and MurderBench', intro(
        'ABOUT', 'Independent evaluation.<br>Accountable claims.',
        'MurderBench is an AI agent evaluation initiative led by Linh Ngo and operated by XP.COM, LLC dba Xenocom.') + '''
<section class="reading"><h2>Why this exists</h2><p>Agents act through tools and safeguards. We want operators to know whether those safeguards enforce the constraint they care about, and whether a repair preserves the useful task.</p><p>We are building a focused engineering evaluation practice. We do not represent ourselves as a university, accredited research lab or a government-supported program.</p><h2>Who does the work</h2><p>Linh Ngo leads the initiative. AI coding and research tools assist with implementation, source discovery and analysis. That assistance is disclosed; automated review is not represented as external peer review.</p><p>No independent reviewers, lab partnerships or funding awards are secured for the proposed guardrail study. We are seeking them and will disclose material relationships.</p><h2>What earns publication</h2><p>A replayable result with clear denominators and uncertainty—or a documented reason to reject an idea. We preserve failed controls, incomplete collections and negative findings.</p><a class="text-link" href="/research.html">Read the evidence record →</a><a class="text-link" href="https://www.linkedin.com/in/ngolinh/">Linh Ngo on LinkedIn ↗</a><a class="text-link" href="https://x.com/fastrocket">Linh Ngo on X ↗</a><h2>Work with us</h2><p>Review a concrete design, help reproduce a result, offer model access, or bring an agent safeguard that needs a bounded evaluation.</p><a class="button" href="/contact.html">Contact ↗</a></section>
''', 'MurderBench is led by Linh Ngo and operated by XP.COM, LLC dba Xenocom. Independent evaluation with disclosed methods, assistance and limitations.')

    page('contact.html', 'Contact Linh Ngo', intro(
        'CONTACT', 'Bring a question<br>we can test.',
        'Method critique, model credits, replication or a specific agent workflow: make the decision concrete.') + '''
<section class="reading"><a class="email" href="mailto:linh@ngo.net">linh@ngo.net ↗</a><p>Linh Ngo<br>XP.COM, LLC dba Xenocom<br>MurderBench evaluation initiative</p><div class="rows"><article><h3>For evaluators</h3><p>Tell us the closest prior experiment, the confound you see, or the evidence that would change your configuration choice.</p></article><article><h3>For sponsors and labs</h3><p>We seek API credits, independent review and scoped support. Public reporting preserves negative outcomes and sponsor disclosure.</p></article><article><h3>For teams using agents</h3><p>Describe one workflow, the tools it can use, the safeguard under consideration and the deployment decision. We will discuss a bounded scope before quoting.</p></article></div><p>Initial messages should contain public or synthetic information. Agree data handling before sharing confidential material, logs or implementation details.</p><a class="text-link" href="https://www.linkedin.com/in/ngolinh/">LinkedIn ↗</a><a class="text-link" href="https://x.com/fastrocket">X ↗</a><a class="text-link" href="/program.html">Current proposal →</a><a class="text-link" href="/services.html">Evaluation service →</a></section>
''', 'Contact Linh Ngo about MurderBench methods, model access, sponsorship, replication or a scoped AI agent safeguard evaluation.')

    artifact_dir = out / 'artifacts'
    for name in ('business-2026-10-04.txt', 'guardrail-coverage-proposal.txt', 'guardrail-source-audit-2026-10-04.txt'):
        (artifact_dir / name).write_bytes((ROOT / 'plans' / name).read_bytes())
    (artifact_dir / 'guardrail-native-primitive.json').write_bytes((ROOT / 'reviews/guardrail-native-primitive.json').read_bytes())
    for target in out.glob('*.html'):
        text = target.read_text(encoding='utf-8')
        text = text.replace('Protocol in development. No model rankings published.',
                            'Operated by XP.COM, LLC dba Xenocom. Methods and limits accompany each study.')
        if target.name in ('index.html', 'guardrail-coverage.html', 'program.html'):
            text = text.replace('<meta property="og:type"', '<meta property="og:image" content="https://murderbench.com/guardrail-coverage-design.png"><meta name="twitter:card" content="summary_large_image"><meta property="og:type"', 1)
        target.write_text(text, encoding='utf-8')
